package com.nypunya.progress.entity;
import javax.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="course_progress",uniqueConstraints=@UniqueConstraint(name="uk_progress_student_course",columnNames={"student_id","course_id"}),indexes={@Index(name="idx_progress_student",columnList="student_id"),@Index(name="idx_progress_course",columnList="course_id")})
public class CourseProgress { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="student_id",nullable=false) private Long studentId; @Column(name="course_id",nullable=false) private Long courseId; @Column(name="completed_items",nullable=false) private Integer completedItems=0; @Column(name="total_items",nullable=false) private Integer totalItems=0; @Column(nullable=false) private Integer percentage=0; @Column(name="last_activity_at",nullable=false) private LocalDateTime lastActivityAt; @PrePersist @PreUpdate void touch(){lastActivityAt=LocalDateTime.now(); if(totalItems==null||totalItems<=0)percentage=0; else percentage=Math.min(100,Math.max(0,(completedItems*100)/totalItems));} public Long getId(){return id;} public Long getStudentId(){return studentId;} public void setStudentId(Long v){studentId=v;} public Long getCourseId(){return courseId;} public void setCourseId(Long v){courseId=v;} public Integer getCompletedItems(){return completedItems;} public void setCompletedItems(Integer v){completedItems=v;} public Integer getTotalItems(){return totalItems;} public void setTotalItems(Integer v){totalItems=v;} public Integer getPercentage(){return percentage;} public LocalDateTime getLastActivityAt(){return lastActivityAt;} }
